-- Generated from user-supplied study-plan tables. No external corrections applied.
-- IMPORTANT: all new plans share plan_number=12; identity must use major + plan number, never plan number alone.
-- Multi-code prerequisites are intentionally NOT modeled as executable dependencies until AND/OR semantics are verified.
begin;

update public.faculties set code = coalesce(code, 'IT') where id = '10000000-0000-0000-0000-000000000002';
update public.majors set code = coalesce(code, 'AI') where id = '10000000-0000-0000-0000-000000000003';


















create temporary table _multi_plan_courses (course_code text primary key, name_ar text, catalog_status text not null) on commit drop;
select '10000000-0000-0000-0000-000000000001',course_code,name_ar,catalog_status,true
from _multi_plan_courses
on conflict (university_id,course_code) do update
set name_ar = case
      when public.courses.catalog_status in ('referenced_only','unknown')
       and excluded.name_ar is not null then excluded.name_ar
      else public.courses.name_ar
    end,
    catalog_status = case
      when excluded.catalog_status='known' and public.courses.catalog_status <> 'known' then 'known'
      else public.courses.catalog_status
    end,
    active = true;

create temporary table _multi_plan_course_seed (plan_id uuid, source_id uuid, group_code text, course_code text, credit_hours numeric(6,2), learning_type text, delivery_mode text, raw_prerequisite_text text, prerequisite_logic_status text, display_order integer, verification_status text) on commit drop;
select s.plan_id,c.id,g.id,s.credit_hours,s.learning_type,s.delivery_mode,s.raw_prerequisite_text,s.prerequisite_logic_status,s.verification_status,s.source_id,s.display_order,true
from _multi_plan_course_seed s
join public.courses c on c.university_id='10000000-0000-0000-0000-000000000001' and c.course_code=s.course_code
join public.requirement_groups g on g.study_plan_id=s.plan_id and g.group_code=s.group_code
on conflict (study_plan_id,course_id) do nothing;

create temporary table _multi_plan_single_prereq (plan_id uuid, target_course_code text, prerequisite_course_code text) on commit drop;
select spc.id,'prerequisite',1,'verified'
from _multi_plan_single_prereq s
join public.courses tc on tc.university_id='10000000-0000-0000-0000-000000000001' and tc.course_code=s.target_course_code
join public.study_plan_courses spc on spc.study_plan_id=s.plan_id and spc.course_id=tc.id
on conflict (study_plan_course_id,dependency_type,group_number) do nothing;
select dg.id,pc.id,case when pc.catalog_status='referenced_only' then 'referenced_only' else 'verified' end
from _multi_plan_single_prereq s
join public.courses tc on tc.university_id='10000000-0000-0000-0000-000000000001' and tc.course_code=s.target_course_code
join public.study_plan_courses spc on spc.study_plan_id=s.plan_id and spc.course_id=tc.id
join public.course_dependency_groups dg on dg.study_plan_course_id=spc.id and dg.dependency_type='prerequisite' and dg.group_number=1
join public.courses pc on pc.university_id='10000000-0000-0000-0000-000000000001' and pc.course_code=s.prerequisite_course_code
on conflict (dependency_group_id,dependency_course_id) do nothing;

commit;

